// Gemini's response nests the actual answer here:
const responseText = $input.first().json.candidates[0].content.parts[0].text;

// Sometimes models wrap JSON in ```json ... ``` — strip that out just in case.
let cleanText = responseText.replace(/```json/g, "").replace(/```/g, "").trim();

let extractedData;
try {
  extractedData = JSON.parse(cleanText);
} catch (error) {
  // If parsing fails, return the raw text so we can see what went wrong
  // instead of the whole workflow silently breaking.
  extractedData = {
    error: "Could not parse Gemini's response as JSON",
    raw_response: cleanText
  };
}

return [{ json: extractedData }];
